def _sha256(data: bytes) -> bytes:
    """sha2_256 digest (32 bytes), used for all three beacon token names."""
    return hashlib.sha256(data).digest()


def legacy_pair_beacon_name(
    offer_id: bytes,
    offer_name: bytes,
    ask_id: bytes,
    ask_name: bytes,
) -> bytes:
    """The pair-beacon token name. The pre-release build's rule.

    ``sha2_256(a1_id ++ offer_name ++ a2_id ++ ask_name)`` where an empty policy
    id (ADA) is substituted with ``0x00`` for *both* legs. The order is
    offer-then-ask (NOT canonically sorted).
    """
    a1 = offer_id if offer_id != b"" else b"\x00"
    a2 = ask_id if ask_id != b"" else b"\x00"
    return _sha256(a1 + offer_name + a2 + ask_name)


def legacy_offer_beacon_name(offer_id: bytes, offer_name: bytes) -> bytes:
    """The offer-beacon token name: ``sha2_256(0x01 ++ offer_id ++ offer_name)``.

    No ``0x00`` substitution: an ADA offer hashes ``sha2_256(0x01)``. The
    pre-release build's rule.
    """
    return _sha256(b"\x01" + offer_id + offer_name)


def legacy_ask_beacon_name(ask_id: bytes, ask_name: bytes) -> bytes:
    """The ask-beacon token name: ``sha2_256(0x02 ++ ask_id ++ ask_name)``.

    No ``0x00`` substitution: an ADA ask hashes ``sha2_256(0x02)``. The
    pre-release build's rule.
    """
    return _sha256(b"\x02" + ask_id + ask_name)


@dataclass
class _OfferAsset(PlutusData):
    """Pre-image of an official offer-beacon name."""

    CONSTR_ID = 0
    policy_id: bytes
    asset_name: bytes


@dataclass
class _AskAsset(PlutusData):
    """Pre-image of an official ask-beacon name."""

    CONSTR_ID = 1
    policy_id: bytes
    asset_name: bytes


@dataclass
class _TradingPair(PlutusData):
    """Pre-image of an official pair-beacon name (offer asset first)."""

    CONSTR_ID = 2
    offer_id: bytes
    offer_name: bytes
    ask_id: bytes
    ask_name: bytes


def pair_beacon_name(
    offer_id: bytes,
    offer_name: bytes,
    ask_id: bytes,
    ask_name: bytes,
) -> bytes:
    """The official pair-beacon name: ``sha2_256(serialiseData(TradingPair))``.

    ADA is ``("", "")``; the offer asset comes first.
    """
    return _sha256(_TradingPair(offer_id, offer_name, ask_id, ask_name).to_cbor())


def offer_beacon_name(offer_id: bytes, offer_name: bytes) -> bytes:
    """The official offer-beacon name: ``sha2_256(serialiseData(OfferAsset))``."""
    return _sha256(_OfferAsset(offer_id, offer_name).to_cbor())


def ask_beacon_name(ask_id: bytes, ask_name: bytes) -> bytes:
    """The official ask-beacon name: ``sha2_256(serialiseData(AskAsset))``."""
    return _sha256(_AskAsset(ask_id, ask_name).to_cbor())


